117	fn text_of(parts: &[ContentPart]) -> String {
118	    let mut s = String::new();
119	    for p in parts {
120	        if let ContentPart::Text { text } = p {
121	            if !s.is_empty() {
122	                s.push('\n');
123	            }
124	            s.push_str(text);
125	        }
126	    }
127	    s
128	}
129	
130	fn user_blocks(content: &[ContentPart]) -> Value {
131	    use paigasus_helikon_core::MediaSource;
132	    let blocks: Vec<Value> = content
133	        .iter()
134	        .filter_map(|p| match p {
135	            ContentPart::Text { text } => Some(json!({"type": "text", "text": text})),
136	            ContentPart::ToolResult { call_id, content } => Some(json!({
137	                "type": "tool_result",
138	                "tool_use_id": call_id,
139	                "content": text_of(content),
140	            })),
141	            ContentPart::Image { source } => match source {
142	                MediaSource::Url { url } => Some(json!({
143	                    "type": "image",
144	                    "source": {"type": "url", "url": url},
145	                })),
146	                MediaSource::Base64 { mime_type, data } => Some(json!({
147	                    "type": "image",
148	                    "source": {
149	                        "type": "base64",
150	                        "media_type": mime_type,
151	                        "data": data,
152	                    },
153	                })),
154	                _ => {
155	                    tracing::warn!(
156	                        target: "paigasus::anthropic::translate",
157	                        "unsupported MediaSource variant; skipping image",
158	                    );
159	                    None
160	                }
161	            },
162	            _ => None,
163	        })
164	        .collect();
165	    Value::Array(blocks)
166	}
167	
168	fn assistant_blocks(content: &[ContentPart]) -> Value {
169	    let blocks: Vec<Value> = content
170	        .iter()
171	        .filter_map(|p| match p {
172	            ContentPart::Text { text } => Some(json!({"type": "text", "text": text})),
173	            ContentPart::ToolUse { call_id, name, args } => Some(json!({
174	                "type": "tool_use",
175	                "id": call_id,
176	                "name": name,
177	                "input": args,
178	            })),
179	            ContentPart::Reasoning { .. } => {
180	                tracing::warn!(
181	                    target: "paigasus::anthropic::translate",
182	                    "dropping ContentPart::Reasoning on input — signature round-trip not yet supported",
183	                );
184	                None
185	            }
186	            _ => None,
187	        })
188	        .collect();
189	    Value::Array(blocks)
190	}
