fn user(s: &str) -> Item {
    Item::UserMessage {
        content: vec![ContentPart::Text { text: s.to_owned() }],
    }
}

fn req_with(messages: Vec<Item>, mutate: impl FnOnce(&mut ModelRequest)) -> ModelRequest {
    let mut r = ModelRequest::new();
    r.messages = messages;
    mutate(&mut r);
    r
}

